const $=s=>document.querySelector(s), E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])), id=()=>globalThis.crypto?.randomUUID?.()||'preview-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2), now=()=>new Date().toISOString();
const KEY='jsi-outreach-workspace-v2', PAGES=[['overview','▦','Overview'],['agents','✧','Discovery agents'],['leads','◎','Leads & review'],['campaigns','↗','Campaigns'],['templates','▤','Template Studio'],['inbox','↩','Inbox'],['dispatch','◷','Dispatch queue'],['senders','✉','Sender accounts'],['assets','▧','Assets & brochures'],['reports','▥','Reports & exports'],['settings','⚙','Settings & AI'],['audit','≡','Audit trail']];
