if(type==='lead'){const old=find('leads',d.id),emails=splitValues(d.emails).map(normalizeEmail),phones=splitValues(d.phones).map(normalizePhone);if(!emails.length||emails.some(v=>!validEmail(v)))return error('Enter at least one valid email; separate multiple addresses with commas.');if(phones.some(v=>!/^\+[1-9]\d{7,14}$/.test(v)))return error('Use international phone format, e.g. +914412345678.');if(emails.some(v=>s.leads.some(l=>l.id!==old?.id&&l.emails.some(e=>e.value===v))))return error('An email already belongs to another organization. Global email duplicates are not allowed.');if(!safeURL(d.source))return error('Use a valid HTTP(S) source URL.');const existingPhone=s.leads.filter(l=>l.id!==old?.id).flatMap(l=>l.phones.map(p=>p.value));if(phones.some(v=>existingPhone.includes(v)))return error('A phone number already belongs to another organization; review the match first.');const l={...old,...d,id:old?.id||id(),at:old?.at||now(),agent:old?.agent||'',basis:old?.basis||'',history:old?.history||[]};l.emails=emails.map(value=>old?.emails.find(e=>e.value===value)||{value,status:s.suppressions.includes(value)?'suppressed':'review',syntax:true,mx:'Not checked',verification:'Not checked',source:d.source,at:now()});l.phones=phones.map(value=>old?.phones.find(p=>p.value===value)||{value,source:d.source,at:now()});if(old){const removed=old.emails.filter(e=>!emails.includes(e.value));for(const e of removed)s.jobs.filter(j=>j.email===e.value&&j.status==='queued').forEach(j=>{j.status='cancelled';j.reason='Email removed from organization'})}derive(l);l.history.unshift({at:now(),action:old?'Organization edited':'Organization added; review required'});if(old)s.leads[s.leads.indexOf(old)]=l;else s.leads.push(l);audit(old?'Organization edited':'Organization added',l.name)}
